// Deterministic cap table calculation engine.
// AI only ever supplies the raw assumptions below — every number in this
// file is computed with plain arithmetic, never generated by a model.

export const DEFAULT_ASSUMPTIONS = {
  companyName: "Company",
  founders: [
    { name: "Founder 1", shares: 4000000 },
    { name: "Founder 2", shares: 4000000 },
  ],
  optionPoolShares: 1000000,
  rounds: [
    { name: "Seed", preMoney: 8000000, investment: 2000000, targetOptionPoolPct: 0.10, liquidationPreference: 1 },
  ],
  safes: [],
};

const num = (v, fallback) => (typeof v === "number" && Number.isFinite(v) ? v : fallback);

function validateFounder(f, i) {
  const src = f && typeof f === "object" ? f : {};
  return {
    name: typeof src.name === "string" && src.name.trim() ? src.name.trim() : `Founder ${i + 1}`,
    shares: Math.max(0, num(src.shares, 0)),
  };
}

function validateRound(r, i) {
  const src = r && typeof r === "object" ? r : {};
  const defaults = DEFAULT_ASSUMPTIONS.rounds[0];
  return {
    name: typeof src.name === "string" && src.name.trim() ? src.name.trim() : `Round ${i + 1}`,
    preMoney: Math.max(0, num(src.preMoney, defaults.preMoney)),
    investment: Math.max(0, num(src.investment, defaults.investment)),
    targetOptionPoolPct: Math.min(0.9, Math.max(0, num(src.targetOptionPoolPct, 0))),
    liquidationPreference: Math.max(0, num(src.liquidationPreference, 1)),
  };
}

function validateSafe(s, i) {
  const src = s && typeof s === "object" ? s : {};
  return {
    name: typeof src.name === "string" && src.name.trim() ? src.name.trim() : `SAFE ${i + 1}`,
    amount: Math.max(0, num(src.amount, 0)),
    cap: Math.max(1, num(src.cap, 1e12)), // effectively "no cap" if missing
    discount: Math.min(0.9, Math.max(0, num(src.discount, 0))),
  };
}

// Fills in anything missing/malformed from an AI-supplied assumptions object
// with the defaults above, so the engine always has a complete, well-typed input.
export function validateAssumptions(raw) {
  const a = raw && typeof raw === "object" ? raw : {};

  const founders = Array.isArray(a.founders) && a.founders.length
    ? a.founders.map(validateFounder)
    : DEFAULT_ASSUMPTIONS.founders.map((f) => ({ ...f }));

  const rounds = Array.isArray(a.rounds) && a.rounds.length
    ? a.rounds.map(validateRound)
    : DEFAULT_ASSUMPTIONS.rounds.map((r) => ({ ...r }));

  const safes = Array.isArray(a.safes) ? a.safes.map(validateSafe) : [];

  return {
    companyName: typeof a.companyName === "string" && a.companyName.trim()
      ? a.companyName.trim()
      : DEFAULT_ASSUMPTIONS.companyName,
    founders,
    optionPoolShares: Math.max(0, num(a.optionPoolShares, DEFAULT_ASSUMPTIONS.optionPoolShares)),
    rounds,
    safes,
  };
}

function totalShares(holders) {
  return holders.reduce((s, h) => s + h.shares, 0);
}

function snapshotOwnership(holders) {
  const total = totalShares(holders);
  return holders.map((h) => ({ name: h.name, type: h.type, shares: h.shares, pct: total > 0 ? h.shares / total : 0 }));
}

// Fixed-point iteration version of the round solver below. No longer used
// by computeCapTable (see solveRoundClosedForm) — kept only so
// lib/capTable.test.js can confirm the closed form gives the same answer.
export function solveRoundIterative(priorFDShares, existingPoolShares, round, safesToConvert) {
  let price = priorFDShares > 0 ? round.preMoney / priorFDShares : 0;
  let poolTopUp = 0;
  let safeShares = 0;
  let safeSharesByName = {};

  for (let iter = 0; iter < 200; iter++) {
    // Cap price uses the pre-money share count, which includes the pool
    // top-up (the pool increase is negotiated as part of the pre-money cap).
    const preMoneyFDForCap = priorFDShares + poolTopUp;
    let nextSafeShares = 0;
    const nextSafeSharesByName = {};
    for (const safe of safesToConvert) {
      const discountPrice = price * (1 - safe.discount);
      const capPrice = preMoneyFDForCap > 0 ? safe.cap / preMoneyFDForCap : Infinity;
      // Whichever price is lower gives the SAFE holder more shares.
      const conversionPrice = Math.min(capPrice, discountPrice);
      const shares = conversionPrice > 0 ? safe.amount / conversionPrice : 0;
      nextSafeSharesByName[safe.name] = shares;
      nextSafeShares += shares;
    }

    const targetPct = round.targetOptionPoolPct;
    const nextPoolTopUpRaw = targetPct > 0
      ? (targetPct * (priorFDShares + nextSafeShares + (price > 0 ? round.investment / price : 0)) - existingPoolShares) / (1 - targetPct)
      : -existingPoolShares;
    const nextPoolTopUp = Math.max(nextPoolTopUpRaw, 0);

    const preMoneyFDSharesForPrice = priorFDShares + nextPoolTopUp + nextSafeShares;
    const nextPrice = preMoneyFDSharesForPrice > 0 ? round.preMoney / preMoneyFDSharesForPrice : 0;

    const converged =
      Math.abs(nextPrice - price) < 1e-9 &&
      Math.abs(nextPoolTopUp - poolTopUp) < 1e-6 &&
      Math.abs(nextSafeShares - safeShares) < 1e-6;

    price = nextPrice;
    poolTopUp = nextPoolTopUp;
    safeShares = nextSafeShares;
    safeSharesByName = nextSafeSharesByName;
    if (converged) break;
  }

  const newInvestorShares = price > 0 ? round.investment / price : 0;
  return { price, poolTopUp, safeShares, safeSharesByName, newInvestorShares };
}

// Solves one round's price per share, option pool top-up, and SAFE
// conversion shares in closed form — no iteration, no circular reference.
//
// Every new share count is a fraction of the post-round fully-diluted total
// T: new investor shares = T * investment/postMoney, the pool after the
// round = T * targetPct (so top-up = that minus the existing pool), and
// each SAFE converts at whichever of its cap price or discount price is
// lower. Substituting all three into "T = prior shares + top-up + SAFE
// shares + investor shares" turns the pool and SAFE terms into K-weighted
// multiples of T, which rearranges into one direct formula for T (see
// solveForT below) — see the comment above solveRoundClosedForm's loop for
// why SAFE cap/discount governance still has to be tried both ways.
//
// A SAFE's cap price and a discount price are each affine in T on their
// own, but which one is *lower* (and therefore governs) can depend on T,
// and so can whether the option pool top-up is positive at all. Those are
// both yes/no questions with only a handful of combinations (pool
// active/inactive x each SAFE cap/discount), so rather than iterating to a
// fixed point, this tries every combination directly and keeps the one
// that's self-consistent — i.e. where solving under that assumption
// actually reproduces that same assumption.
function solveRoundClosedForm(priorFDShares, existingPoolShares, round, safesToConvert) {
  const P = priorFDShares;
  const E = existingPoolShares;
  const postMoney = round.preMoney + round.investment;
  const targetPct = round.targetOptionPoolPct;
  const n = safesToConvert.length;

  function solveForT(poolActive, capMask) {
    let Kcap = 0;
    let Kdisc = 0;
    safesToConvert.forEach((safe, i) => {
      if ((capMask >> i) & 1) Kcap += safe.amount / safe.cap;
      else Kdisc += safe.amount / (1 - safe.discount);
    });

    let T;
    if (poolActive) {
      const denominator = 1 - targetPct * (1 + Kcap) - (Kdisc + round.investment) / postMoney;
      if (!(denominator > 0)) return null;
      T = ((P - E) * (1 + Kcap)) / denominator;
    } else {
      const denominator = 1 - (Kdisc + round.investment) / postMoney;
      if (!(denominator > 0)) return null;
      T = (P * (1 + Kcap)) / denominator;
    }
    if (!Number.isFinite(T) || T <= 0) return null;

    // The pool-active/inactive assumption must match what T actually implies:
    // active requires a genuinely positive top-up; inactive requires the
    // existing pool already meets or exceeds the target without one.
    const naturalTopUp = T * targetPct - E;
    if (poolActive && naturalTopUp < -1e-6) return null;
    if (!poolActive && naturalTopUp > 1e-6) return null;
    const poolTopUp = poolActive ? Math.max(naturalTopUp, 0) : 0;

    // Each SAFE's assumed regime (cap vs. discount) must match which price
    // is actually lower once T (and so price and the pool top-up) is known.
    const preMoneyFDForCap = P + poolTopUp;
    const price = postMoney / T;
    const safeSharesByName = {};
    const safeMethodByName = {};
    let consistent = true;
    safesToConvert.forEach((safe, i) => {
      const capPrice = preMoneyFDForCap > 0 ? safe.cap / preMoneyFDForCap : Infinity;
      const discPrice = price * (1 - safe.discount);
      const assumedCapGoverns = !!((capMask >> i) & 1);
      const capActuallyGoverns = capPrice <= discPrice;
      if (capActuallyGoverns !== assumedCapGoverns) consistent = false;
      const conversionPrice = Math.min(capPrice, discPrice);
      safeSharesByName[safe.name] = conversionPrice > 0 ? safe.amount / conversionPrice : 0;
      safeMethodByName[safe.name] = capActuallyGoverns ? "cap" : "discount";
    });
    if (!consistent) return null;

    const newInvestorShares = (T * round.investment) / postMoney;
    return { price, poolActive, poolTopUp, safeSharesByName, safeMethodByName, newInvestorShares };
  }

  for (const poolActive of [true, false]) {
    for (let mask = 0; mask < (1 << n); mask++) {
      const result = solveForT(poolActive, mask);
      if (result) return result;
    }
  }
  // Should be unreachable for sane inputs (one combination is always
  // self-consistent), but never throw — fall back to the plainest case.
  return solveForT(false, 0) || { price: 0, poolActive: false, poolTopUp: 0, safeSharesByName: {}, safeMethodByName: {}, newInvestorShares: 0 };
}

// Walks every round in order, converting all SAFEs at the first round and
// solving each round's option-pool shuffle + new-money math. Returns the
// full holder list plus a per-round breakdown (price, shares issued,
// ownership before/after).
export function computeCapTable(rawAssumptions) {
  const a = validateAssumptions(rawAssumptions);

  const holders = [
    ...a.founders.map((f) => ({ name: f.name, type: "founder", shares: f.shares, invested: 0, liqPref: 0 })),
  ];
  if (a.optionPoolShares > 0) {
    holders.push({ name: "Option Pool", type: "pool", shares: a.optionPoolShares, invested: 0, liqPref: 0 });
  }

  const roundResults = [];

  a.rounds.forEach((round, ri) => {
    const priorFDShares = totalShares(holders);
    const ownershipBefore = snapshotOwnership(holders);
    const safesToConvert = ri === 0 ? a.safes : [];

    let pool = holders.find((h) => h.type === "pool");
    const existingPoolShares = pool ? pool.shares : 0;

    const { price, poolActive, poolTopUp, safeSharesByName, safeMethodByName, newInvestorShares } =
      solveRoundClosedForm(priorFDShares, existingPoolShares, round, safesToConvert);

    if (poolTopUp > 0) {
      if (!pool) {
        pool = { name: "Option Pool", type: "pool", shares: 0, invested: 0, liqPref: 0 };
        holders.push(pool);
      }
      pool.shares += poolTopUp;
    }

    const safeConversions = safesToConvert.map((safe) => {
      const shares = safeSharesByName[safe.name] || 0;
      holders.push({ name: safe.name, type: "safe", shares, invested: safe.amount, liqPref: round.liquidationPreference });
      return { name: safe.name, shares, invested: safe.amount, method: safeMethodByName[safe.name] };
    });

    holders.push({
      name: `${round.name} investor`,
      type: "investor",
      shares: newInvestorShares,
      invested: round.investment,
      liqPref: round.liquidationPreference,
    });

    const fullyDilutedSharesAfter = totalShares(holders);
    const ownershipAfter = snapshotOwnership(holders);

    roundResults.push({
      name: round.name,
      preMoney: round.preMoney,
      investment: round.investment,
      postMoney: round.preMoney + round.investment,
      pricePerShare: price,
      poolActive,
      optionPoolTopUpShares: poolTopUp,
      safeConversions,
      newInvestorShares,
      fullyDilutedSharesBefore: priorFDShares,
      fullyDilutedSharesAfter,
      ownershipBefore,
      ownershipAfter,
    });
  });

  return {
    assumptions: a,
    holders: holders.map((h) => ({ ...h })),
    rounds: roundResults,
    finalOwnership: roundResults.length ? roundResults[roundResults.length - 1].ownershipAfter : snapshotOwnership(holders),
  };
}

// Resolves the exit waterfall for a single exit value: every preferred
// holder (any holder with invested > 0) either takes its liquidation
// preference or converts to common and shares pro rata, whichever is worth
// more. Converting changes the per-share value for everyone still
// converting, which can change another holder's decision — so this is
// resolved by iterating the decision set until no holder wants to flip.
//
// Simplification: all preference claims are pari passu (no seniority
// stack). If the exit can't cover every claim taking preference, proceeds
// are split pro rata among those claims and nothing is left for common —
// this is what "pays investors first" means below total preferences.
export function computeExitWaterfall(capTableResult, exitValue) {
  const holders = capTableResult.holders;
  const preferredHolders = holders.filter((h) => h.invested > 0);
  const commonHolders = holders.filter((h) => h.invested === 0);

  let convertSet = new Set();
  let payouts = {};

  for (let iter = 0; iter < 100; iter++) {
    const takingPref = preferredHolders.filter((h) => !convertSet.has(h.name));
    const totalPrefClaim = takingPref.reduce((s, h) => s + h.invested * h.liqPref, 0);

    const nextPayouts = {};
    let remaining;
    if (exitValue <= totalPrefClaim) {
      takingPref.forEach((h) => {
        nextPayouts[h.name] = totalPrefClaim > 0 ? exitValue * ((h.invested * h.liqPref) / totalPrefClaim) : 0;
      });
      remaining = 0;
    } else {
      takingPref.forEach((h) => { nextPayouts[h.name] = h.invested * h.liqPref; });
      remaining = exitValue - totalPrefClaim;
    }

    const converting = [...commonHolders, ...preferredHolders.filter((h) => convertSet.has(h.name))];
    const convertingShares = totalShares(converting);
    const perShare = convertingShares > 0 ? remaining / convertingShares : 0;
    converting.forEach((h) => { nextPayouts[h.name] = (nextPayouts[h.name] || 0) + h.shares * perShare; });

    let changed = false;
    preferredHolders.forEach((h) => {
      const asConvertedValue = h.shares * perShare;
      const prefValue = h.invested * h.liqPref;
      const shouldConvert = asConvertedValue > prefValue;
      const currentlyConverting = convertSet.has(h.name);
      if (shouldConvert !== currentlyConverting) {
        changed = true;
        if (shouldConvert) convertSet.add(h.name);
        else convertSet.delete(h.name);
      }
    });

    payouts = nextPayouts;
    if (!changed) break;
  }

  return holders.map((h) => ({ name: h.name, type: h.type, payout: payouts[h.name] || 0, converted: convertSet.has(h.name) }));
}

// Payout table across several multiples of the last round's post-money
// valuation (e.g. 0.5x, 1x, 2x, 5x, 10x).
export function computePayoutTable(capTableResult, multiples = [0.5, 1, 2, 5, 10]) {
  const { rounds } = capTableResult;
  if (!rounds.length) return { basis: 0, multiples: [], columns: [] };

  const basis = rounds[rounds.length - 1].postMoney;
  const columns = multiples.map((m) => ({
    multiple: m,
    exitValue: basis * m,
    payouts: computeExitWaterfall(capTableResult, basis * m),
  }));

  return { basis, multiples, columns };
}
